  1→// Package factoryaidroid implements the Agent interface for Factory AI Droid.
  2→package factoryaidroid
  3→
  4→import (
  5→	"errors"
  6→	"fmt"
  7→	"io"
  8→	"os"
  9→	"path/filepath"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/agent"
 12→	"github.com/entireio/cli/cmd/entire/cli/paths"
 13→)
 14→
 15→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 16→func init() {
 17→	agent.Register(agent.AgentNameFactoryAIDroid, NewFactoryAIDroidAgent)
 18→}
 19→
 20→// FactoryAIDroidAgent implements the agent.Agent interface for Factory AI Droid.
 21→//
 22→//nolint:revive // FactoryAIDroidAgent is clearer than Agent in this context
 23→type FactoryAIDroidAgent struct{}
 24→
 25→// NewFactoryAIDroidAgent creates a new Factory AI Droid agent instance.
 26→func NewFactoryAIDroidAgent() agent.Agent {
 27→	return &FactoryAIDroidAgent{}
 28→}
 29→
 30→// Name returns the agent registry key.
 31→func (f *FactoryAIDroidAgent) Name() agent.AgentName { return agent.AgentNameFactoryAIDroid }
 32→
 33→// Type returns the agent type identifier.
 34→func (f *FactoryAIDroidAgent) Type() agent.AgentType { return agent.AgentTypeFactoryAIDroid }
 35→
 36→// Description returns a human-readable description.
 37→func (f *FactoryAIDroidAgent) Description() string {
 38→	return "Factory AI Droid - agent-native development platform"
 39→}
 40→
 41→// ProtectedDirs returns directories that Factory AI Droid uses for config/state.
 42→func (f *FactoryAIDroidAgent) ProtectedDirs() []string { return []string{".factory"} }
 43→
 44→// DetectPresence checks if Factory AI Droid is configured in the repository.
 45→func (f *FactoryAIDroidAgent) DetectPresence() (bool, error) {
 46→	repoRoot, err := paths.RepoRoot()
 47→	if err != nil {
 48→		repoRoot = "."
 49→	}
 50→	if _, err := os.Stat(filepath.Join(repoRoot, ".factory")); err == nil {
 51→		return true, nil
 52→	}
 53→	return false, nil
 54→}
 55→
 56→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 57→func (f *FactoryAIDroidAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 58→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 59→	if err != nil {
 60→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 61→	}
 62→	return data, nil
 63→}
 64→
 65→// ChunkTranscript splits a JSONL transcript at line boundaries.
 66→func (f *FactoryAIDroidAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
 67→	chunks, err := agent.ChunkJSONL(content, maxSize)
 68→	if err != nil {
 69→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
 70→	}
 71→	return chunks, nil
 72→}
 73→
 74→// ReassembleTranscript concatenates JSONL chunks with newlines.
 75→func (f *FactoryAIDroidAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
 76→	return agent.ReassembleJSONL(chunks), nil
 77→}
 78→
 79→// GetHookConfigPath returns the path to Factory AI Droid's hook config file.
 80→func (f *FactoryAIDroidAgent) GetHookConfigPath() string { return ".factory/settings.json" }
 81→
 82→// SupportsHooks returns true as Factory AI Droid supports lifecycle hooks.
 83→func (f *FactoryAIDroidAgent) SupportsHooks() bool { return true }
 84→
 85→// ParseHookInput parses Factory AI Droid hook input from stdin.
 86→func (f *FactoryAIDroidAgent) ParseHookInput(_ agent.HookType, r io.Reader) (*agent.HookInput, error) {
 87→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](r)
 88→	if err != nil {
 89→		return nil, err
 90→	}
 91→	return &agent.HookInput{
 92→		SessionID:  raw.SessionID,
 93→		SessionRef: raw.TranscriptPath,
 94→	}, nil
 95→}
 96→
 97→// GetSessionID extracts the session ID from hook input.
 98→func (f *FactoryAIDroidAgent) GetSessionID(input *agent.HookInput) string { return input.SessionID }
 99→
100→// GetSessionDir is not implemented for Factory AI Droid.
101→func (f *FactoryAIDroidAgent) GetSessionDir(_ string) (string, error) {
102→	return "", errors.New("not implemented")
103→}
104→
105→// ResolveSessionFile returns the path to a Factory AI Droid session file.
106→func (f *FactoryAIDroidAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
107→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
108→}
109→
110→// ReadSession is not implemented for Factory AI Droid.
111→func (f *FactoryAIDroidAgent) ReadSession(_ *agent.HookInput) (*agent.AgentSession, error) {
112→	return nil, errors.New("not implemented")
113→}
114→
115→// WriteSession is not implemented for Factory AI Droid.
116→func (f *FactoryAIDroidAgent) WriteSession(_ *agent.AgentSession) error {
117→	return errors.New("not implemented")
118→}
119→
120→// FormatResumeCommand returns the command to resume a Factory AI Droid session.
121→func (f *FactoryAIDroidAgent) FormatResumeCommand(sessionID string) string {
122→	return "droid --session-id " + sessionID
123→}
