 81→	// Read existing settings if they exist
 82→	var rawSettings map[string]json.RawMessage
 83→
 84→	// rawHooks preserves unknown hook types
 85→	var rawHooks map[string]json.RawMessage
 86→
 87→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 88→	var rawPermissions map[string]json.RawMessage
 89→
 90→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from cwd + fixed path
 91→	if readErr == nil {
 92→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 93→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 94→		}
 95→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 96→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 97→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 98→			}
 99→		}
100→		if permRaw, ok := rawSettings["permissions"]; ok {
101→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
102→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
103→			}
104→		}
105→	} else {
106→		rawSettings = make(map[string]json.RawMessage)
107→	}
108→
109→	if rawHooks == nil {
110→		rawHooks = make(map[string]json.RawMessage)
111→	}
112→	if rawPermissions == nil {
113→		rawPermissions = make(map[string]json.RawMessage)
114→	}
115→
116→	// Parse only the hook types we need to modify
117→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse, preCompact []FactoryHookMatcher
118→	parseHookType(rawHooks, "SessionStart", &sessionStart)
119→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
120→	parseHookType(rawHooks, "Stop", &stop)
121→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
122→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
123→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
124→	parseHookType(rawHooks, "PreCompact", &preCompact)
125→
126→	// If force is true, remove all existing Entire hooks first
127→	if force {
128→		sessionStart = removeEntireHooks(sessionStart)
129→		sessionEnd = removeEntireHooks(sessionEnd)
130→		stop = removeEntireHooks(stop)
131→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
132→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
133→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
134→		preCompact = removeEntireHooks(preCompact)
135→	}
