137→	// Define hook commands
138→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, preCompactCmd string
139→	if localDev {
140→		sessionStartCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-start"
141→		sessionEndCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid session-end"
142→		stopCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid stop"
143→		userPromptSubmitCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid user-prompt-submit"
144→		preTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-tool-use"
145→		postTaskCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid post-tool-use"
146→		preCompactCmd = "go run ${FACTORY_PROJECT_DIR}/cmd/entire/main.go hooks factoryai-droid pre-compact"
147→	} else {
148→		sessionStartCmd = "entire hooks factoryai-droid session-start"
149→		sessionEndCmd = "entire hooks factoryai-droid session-end"
150→		stopCmd = "entire hooks factoryai-droid stop"
151→		userPromptSubmitCmd = "entire hooks factoryai-droid user-prompt-submit"
152→		preTaskCmd = "entire hooks factoryai-droid pre-tool-use"
153→		postTaskCmd = "entire hooks factoryai-droid post-tool-use"
154→		preCompactCmd = "entire hooks factoryai-droid pre-compact"
155→	}
