157→	count := 0
158→
159→	// Add hooks if they don't exist
160→	if !hookCommandExists(sessionStart, sessionStartCmd) {
161→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
162→		count++
163→	}
164→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
165→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
166→		count++
167→	}
168→	if !hookCommandExists(stop, stopCmd) {
